const noop = () => {};

function compactReviewButtonLabel(label: string, fallback: string) {
  const interval = label.match(/\(([^)]+)\)/)?.[1]?.trim();
  if (interval) {
    return { primary: interval, secondary: null as string | null };
  }

  if (/^good$/i.test(label.trim())) {
    return { primary: "✓", secondary: "Cram" };
  }

  return { primary: fallback, secondary: null as string | null };
}

